    description: Builds lists, segments, campaigns and flows. No raw PII exports.
    includes: [analyst]
  analyst:
    description: Read-only metrics and reporting.
  support:
    description: Looks up and fixes individual profiles; sees contact details.
  viewer:
    description: Read-only, no PII.

roleSets:
  readers: [account_admin, marketer, analyst, support, viewer]
  builders: [account_admin, marketer]

permissionSets:
  campaigns:
    read: [campaigns.list, campaigns.get]
    write: [campaigns.list, campaigns.get, campaigns.create, campaigns.update]
  profiles:
    read: [profiles.get, profiles.list]

customRoles:
  campaign_reviewer: { campaigns: read, profiles: read }

tools:
  profiles.get: { allow: ["@readers"], scopes: [profiles:read], labels: [pii], toolset: profiles }
  profiles.list: { allow: ["@readers"], scopes: [profiles:read], labels: [pii], toolset: profiles, limits: { page_size: { min: 1, max: 100, integer: true, optional: true } } }
  profiles.create: { allow: [marketer, support], scopes: [profiles:write], toolset: profiles, limits: { email: { maxLength: 254, pattern: "[^@]+@[^@]+\\.[A-Za-z]{2,}" } } }
  profiles.update: { allow: [support, marketer], scopes: [profiles:write], toolset: profiles }
  profiles.delete:
    allow: [account_admin]
    scopes: [profiles:write]
    approve: true
    toolset: profiles
  profiles.export:
    allow: [account_admin, marketer]
    scopes: [profiles:read, data:export]
    labels: [pii, export]
    toolset: profiles
    limits: { format: { in: [csv, json] } }
    budget: { max: 5, per: day, shared: tenant, name: exports }
  data_privacy.delete_profile: { allow: [account_admin, support], scopes: [data-privacy:write], approve: true, labels: [pii] }
  lists.list: { allow: ["@readers"], scopes: [lists:read], toolset: lists }
  lists.create: { allow: ["@builders"], scopes: [lists:write], toolset: lists, limits: { name: { maxLength: 100 } } }
  lists.add_profiles: { allow: ["@builders"], scopes: [lists:write], toolset: lists, limits: { count: { min: 1, max: 1000, integer: true } } }
  segments.list: { allow: ["@readers"], scopes: [segments:read], toolset: lists }
  segments.create: { allow: ["@builders"], scopes: [segments:write], toolset: lists }
  campaigns.list: { allow: ["@readers"], scopes: [campaigns:read], toolset: campaigns }
  campaigns.get: { allow: ["@readers"], scopes: [campaigns:read], toolset: campaigns }
  campaigns.create: { allow: ["@builders"], scopes: [campaigns:write], toolset: campaigns, limits: { channel: { in: [email, sms, push] } } }
  campaigns.update: { allow: ["@builders"], scopes: [campaigns:write], toolset: campaigns }
  campaigns.send:
    allow:
      marketer: { recipients: { max: 50000 } }
      account_admin: true
    scopes: [campaigns:write]
    toolset: campaigns
    limits: { recipients: { min: 1, integer: true } }
    approve: { when: { recipients: { min: 10000 } } }
    budget:
      - { max: 10, per: day, shared: tenant, name: sends }
      - { max: 1000000, per: day, sum: recipients, shared: tenant, name: send-volume }
  flows.list: { allow: ["@readers"], scopes: [flows:read], toolset: flows }
  flows.create: { allow: ["@builders"], scopes: [flows:write], toolset: flows }
  flows.update_status:
    allow: ["@builders"]
    scopes: [flows:write]
    toolset: flows
    limits: { status: { in: [draft, manual, live] } }
    approve: { when: { status: { eq: live } } }
  templates.list: { allow: ["@readers"], scopes: [templates:read], toolset: campaigns }
  templates.create: { allow: ["@builders"], scopes: [templates:write], toolset: campaigns, limits: { html: { maxLength: 200000 } } }
  metrics.query: { allow: ["@readers"], scopes: [metrics:read], toolset: analytics, limits: { days: { min: 1, max: 365, integer: true } } }
  events.track: { allow: [marketer, support], scopes: [events:write], toolset: analytics, budget: { max: 600, per: minute, shared: tenant, burst: { max: 50, per: 1000 } } }
  accounts.list: { allow: ["@readers"], scopes: [accounts:read] }

scopes:
  implies:
    "account:admin": [profiles:write, lists:write, segments:write, campaigns:write, flows:write, templates:write, events:write, data:export, data-privacy:write, accounts:read]

tenants:
  accounts: [acme, globex, initech, umbrella]
  groups:
    agency_clients: [acme, globex]

output:
  labelRules:
    - { labels: [pii, export], allowRoles: [account_admin] }
  redact:
    - { label: pii, fields: [email, phone_number, "location.*", "profiles.*.email", "profiles.*.phone_number"], unlessRoles: [account_admin, support] }

toolsets:
  default: [profiles, lists, campaigns, flows, analytics]
  ungrouped: show

delegation:
  actors:
    claude-desktop: { tools: ["*.list", "*.get", "metrics.query", "campaigns.create", "campaigns.update"] }
    n8n-sync: { tools: [profiles.create, profiles.update, lists.add_profiles, events.track], scopes: [profiles:write, lists:write, events:write] }
    reporting-agent: { tools: [metrics.query, campaigns.list, flows.list], scopes: [metrics:read, campaigns:read, flows:read] }

limits:
  - { tool: "*", max: 1200, per: minute, shared: client, name: per-client }

